WFJ.Data.add("book", {
  ["7a49c0b5a1dcd515"] = { "Temo che mio padre abbia commesso un grave errore quando ha deciso di restare a difendere la nostra casa. Le forze del Flagello imperversano nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ e, sebbene siamo ben fortificati e ben forniti, dopo il tradimento di mio fratello Devlin non abbiamo la forza né il numero per resistere ai loro continui assalti.\n\nSe ricevi questa lettera, Yvette, sappi che Devlin è un traditore.", "." },
  ["7a53bfc7588e851e"] = { "Il congedo della bestia:\n\nDopo trenta minuti, la bestia tornerà alla sua dimora nel Nether.\n\nNota:\n\nNella sua foga, la bestia POTREBBE gettarsi da un dirupo o precipitare da una montagna. Non piangere la perdita del ⟦Felhound Tracker=Vilsegugio Braccatore⟧: evocane un altro.", "." },
  ["7a7875fb13409980"] = { "Comandante,\n\nTorna a Orgrimmar. Le tue forze sono insufficienti. Dobbiamo rivalutare la nostra posizione alla luce delle nuove informazioni.\n\nPresenti molti Shadowsworn e ogre. Demoni a guardia del Portale Oscuro.\n\n-Thrall, Capoguerra dell'⟦Horde=Orda⟧", "." },
  ["7a83b1c7e8f2ad1d"] = { "Il nostro primo piano è già fallito!\n\nFist è riuscito a scambiare il ruolino delle guardie per i turni nei tunnel di quella sera, ma per via di alcuni sforzi imprevisti di certi cittadini di ⟦Stormwind=Roccavento⟧, il nostro bersaglio è riuscito a fuggire prima che potessimo catturarlo. Ma avevamo previsto simili eventualità. Il piano 2 è stato messo in moto ed era già ben avviato prima che la nostra imboscata scattasse a ⟦Stormwind=Roccavento⟧.", "." },
  ["7aacda83478a4c59"] = { "Man mano che i loro poteri crescevano, Azshara e gli Alti Nobili subirono un netto cambiamento. L'altezzosa e distaccata classe superiore divenne sempre più insensibile e crudele verso gli altri elfi della notte. Un velo cupo e tenebroso offuscò la bellezza un tempo incantevole di Azshara. La regina cominciò ad allontanarsi dai suoi sudditi devoti e si rifiutò di avere rapporti con chiunque non fosse uno dei suoi fidati sacerdoti Alti Nobili.", "." },
})
